BEGIN;
-- Generated by `supabase migration new e2_read_receipt_labels`, then moved above
-- the canonical frontier. Presentation only: existing successful read receipts
-- describe a lookup, not a business change. No event or historical row is written.
DO $$ BEGIN
  IF to_regprocedure('public._workspace_event_display_before_e02_reads(text,text,text)') IS NULL THEN
    ALTER FUNCTION public._workspace_event_display(text,text,text) RENAME TO _workspace_event_display_before_e02_reads;
  END IF;
END $$;
REVOKE ALL ON FUNCTION public._workspace_event_display_before_e02_reads(text,text,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public._workspace_event_display(_source_kind text,_outcome text,_capability text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$
DECLARE result jsonb;
BEGIN
  result:=public._workspace_event_display_before_e02_reads(_source_kind,_outcome,_capability);
  IF _source_kind='capability_run' AND _outcome='capability_succeeded' THEN
    CASE _capability
      WHEN 'read_sales_collections' THEN
        result:=result||jsonb_build_object('title','Read collection records',
          'summary','PAIGE read existing collection records to answer you. No business records were changed.');
      WHEN 'read_sales_commercial_package' THEN
        result:=result||jsonb_build_object('title','Read commercial records',
          'summary','PAIGE read the existing invoice package to answer you. No business records were changed.');
      ELSE NULL;
    END CASE;
  END IF;
  RETURN result;
END $$;
REVOKE ALL ON FUNCTION public._workspace_event_display(text,text,text) FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON FUNCTION public._workspace_event_display(text,text,text) IS
  'Existing Rail display chain. Only successful read_sales_collections/read_sales_commercial_package receipts receive explicit lookup wording. Every other key, family, outcome and actor attribution delegates unchanged. No receipt history rewrite or authorization change.';
COMMIT;
